import CoreGraphics

public struct FLXRadiusScale: Sendable {
    public var base: CGFloat

    public init(base: CGFloat) {
        self.base = base
    }

    public var sm: CGFloat { max(0, base - 4) }
    public var md: CGFloat { max(0, base - 2) }
    public var lg: CGFloat { base }
    public var xl: CGFloat { base + 4 }
    public var xxl: CGFloat { base + 8 }
    public var full: CGFloat { 9999 }
}

import CoreGraphics

public enum FLXBorderWidth {
    public static let thin: CGFloat = 1
    public static let regular: CGFloat = 1.5
    public static let thick: CGFloat = 2
}

public enum FLXOpacity {
    public static let disabled: Double = 0.5
    public static let pressed: Double = 0.7
    public static let destructiveDark: Double = 0.6
}

import SwiftUI

public enum FLXTypography {
    case largeTitle
    case title
    case title2
    case title3

    case headline
    case body
    case callout

    case subheadline
    case footnote
    case caption
    case caption2

    public var weight: Font.Weight {
        switch self {
        case .largeTitle, .title: .bold
        case .title2, .title3, .headline: .semibold
        case .body, .callout, .subheadline, .footnote, .caption, .caption2: .regular
        }
    }

    public var textStyle: Font.TextStyle {
        switch self {
        case .largeTitle: .largeTitle
        case .title: .title
        case .title2: .title2
        case .title3: .title3
        case .headline: .headline
        case .body: .body
        case .callout: .callout
        case .subheadline: .subheadline
        case .footnote: .footnote
        case .caption: .caption
        case .caption2: .caption2
        }
    }

    public static func control(_ controlSize: ControlSize) -> FLXTypography {
        switch controlSize {
        case .mini, .small: .subheadline
        case .regular, .large, .extraLarge: .body
        @unknown default: .body
        }
    }
}

private struct FLXFontModifier: ViewModifier {
    private let typography: FLXTypography
    private let weight: Font.Weight

    init(typography: FLXTypography, weight: Font.Weight?) {
        self.typography = typography
        self.weight = weight ?? typography.weight
    }

    func body(content: Content) -> some View {
        content.font(.system(typography.textStyle, weight: weight))
    }
}

extension View {
    public func flxFont(_ typography: FLXTypography, weight: Font.Weight? = nil) -> some View {
        modifier(FLXFontModifier(typography: typography, weight: weight))
    }
}

import SwiftUI

extension Color {
    public init(flxLight light: Color, dark: Color) {
        #if os(macOS)
        self.init(NSColor(name: nil) { appearance in
            switch appearance.bestMatch(from: [.aqua, .darkAqua]) {
            case .darkAqua: NSColor(dark)
            default: NSColor(light)
            }
        })
        #else
        self.init(UIColor { traits in
            traits.userInterfaceStyle == .dark ? UIColor(dark) : UIColor(light)
        })
        #endif
    }
}

import Foundation

public struct FLXTheme: Sendable {
    public var colors: FLXColorTokens
    public var radius: FLXRadiusScale

    public init(colors: FLXColorTokens, radius: FLXRadiusScale) {
        self.colors = colors
        self.radius = radius
    }
}

import SwiftUI

private struct FLXThemeKey: EnvironmentKey {
    static let defaultValue: FLXTheme = .default
}

extension EnvironmentValues {
    public var flxTheme: FLXTheme {
        get { self[FLXThemeKey.self] }
        set { self[FLXThemeKey.self] = newValue }
    }
}

extension View {
    public func flxTheme(_ theme: FLXTheme) -> some View {
        environment(\.flxTheme, theme)
    }
}
